import { CALLIS_ROAD_METADATA, type FieldMetadata, type SurveyAlignment, type SurveyLayers } from './callisRoad'

/** Full reconstruction of the Aug 30 flight over the same field, generated by pipeline/. */
const GENERATED_SURVEY = {
  id: 'callis-road-2026-08-30',
  name: 'Callis Road (Field 175)',
  date: 'August 30, 2026 flight',
} as const

type GdalInfo = { wgs84Extent?: { coordinates: number[][][] } }
type OdmStats = { odm_processing_statistics?: { average_gsd?: number }, reconstruction_statistics?: { reconstructed_shots_count?: number } }
type Heights = { bounds: FieldMetadata['bounds'] } & NonNullable<SurveyLayers['heights']>

async function getJson<T>(url: string, signal: AbortSignal): Promise<T> {
  const response = await fetch(url, { signal })
  if (!response.ok) throw new Error(`${url}: ${response.status}`)
  return response.json() as Promise<T>
}

async function exists(url: string, signal: AbortSignal) {
  const response = await fetch(url, { method: 'HEAD', signal })
  // Vite's dev server answers unknown paths with index.html, so check the type too.
  return response.ok && !(response.headers.get('content-type') ?? '').includes('text/html')
}

/**
 * The survey the viewer opens: the generated full reconstruction when its files are present,
 * otherwise the checked-in orthophoto survey. Generated data is gitignored (see pipeline/README.md).
 */
export async function resolveActiveSurvey(signal: AbortSignal): Promise<FieldMetadata> {
  // Relative to the page, so the site works under any URL prefix.
  const base = `data/${GENERATED_SURVEY.id}`
  try {
    if (!(await exists(`${base}/heights.json`, signal))) return CALLIS_ROAD_METADATA
    const [heights, ortho, stats] = await Promise.all([
      getJson<Heights>(`${base}/heights.json`, signal),
      getJson<GdalInfo>(`${base}/orthophoto.info.json`, signal),
      getJson<OdmStats>(`${base}/stats.json`, signal).catch(() => ({} as OdmStats)),
    ])
    const alignment = await getJson<SurveyAlignment>(`${base}/alignment.json`, signal).catch(() => undefined)
    // Tile pyramids from pipeline/tile_imagery.sh stream far better than single large images.
    const tiled = await exists(`${base}/ortho/14`, signal).catch(() => false)
      || await exists(`${base}/ortho/tilemapresource.xml`, signal).catch(() => false)
    if (tiled) {
      for (const key of ['dsm', 'dtm', 'canopy'] as const) {
        const raster = heights[key]
        if (raster) raster.tilesUrl = `${base}/tiles-${key}/{z}/{x}/{y}.webp`
      }
    }
    const ring = ortho.wgs84Extent?.coordinates[0] ?? []
    const lons = ring.map(([lon]) => lon)
    const lats = ring.map(([, lat]) => lat)
    const bounds = ring.length
      ? { west: Math.min(...lons), south: Math.min(...lats), east: Math.max(...lons), north: Math.max(...lats) }
      : heights.bounds
    const gsd = stats.odm_processing_statistics?.average_gsd
    const shots = stats.reconstruction_statistics?.reconstructed_shots_count

    return {
      ...CALLIS_ROAD_METADATA,
      name: GENERATED_SURVEY.name,
      date: GENERATED_SURVEY.date,
      gsd: gsd ? `${gsd.toFixed(1)} cm/px` : CALLIS_ROAD_METADATA.gsd,
      shotsCount: shots ?? CALLIS_ROAD_METADATA.shotsCount,
      bounds,
      // With tiles, the single image is only the panel's layer icon, so use the small thumbnail.
      orthophotoUrl: tiled ? `${base}/orthophoto-thumb.webp` : `${base}/orthophoto.webp`,
      shotsUrl: `${base}/shots.geojson`,
      boundsUrl: `${base}/bounds.geojson`,
      layers: {
        alignment,
        orthoTilesUrl: tiled ? `${base}/ortho/{z}/{x}/{y}.webp` : undefined,
        meshUrl: `${base}/mesh/tileset.json`,
        splatUrl: (await exists(`${base}/splat/tileset.json`, signal)) ? `${base}/splat/tileset.json` : undefined,
        heights,
      },
    }
  } catch (error) {
    if (!signal.aborted) console.warn('Generated survey unavailable; showing the orthophoto survey.', error)
    return CALLIS_ROAD_METADATA
  }
}
